await page.setViewport({ width: 1280, height: 800 });

async function stats(file) {
  const b64 = fs.readFileSync(file).toString('base64');
  return page.evaluate(async (b64) => {
    const img = new Image();
    img.src = 'data:image/png;base64,' + b64;
    await img.decode();
    const c = document.createElement('canvas');
    c.width = img.width; c.height = img.height;
    const ctx = c.getContext('2d');
    ctx.drawImage(img, 0, 0);
    const d = ctx.getImageData(0, 0, c.width, c.height).data;

    const near = (r, g, b, ref, tol) =>
      Math.abs(r - ref[0]) <= tol && Math.abs(g - ref[1]) <= tol && Math.abs(b - ref[2]) <= tol;

    const targets = {
      background: [245, 247, 250, 8],   // #F5F7FA 点阵背景
      shellFill:  [219, 230, 255, 12],  // #dbe6ff 壳体填充
      diskBlue:   [123, 157, 248, 16],  // #7b9df8 磁片
      shutterGray:[74, 85, 104, 12],    // #4a5568 快门金属
      inkBlue:    [65, 105, 225, 40]    // #4169E1 工程蓝线
    };
    const out = {};
    for (const k of Object.keys(targets)) out[k] = 0;

    for (let i = 0; i < d.length; i += 4) {
      const r = d[i], g = d[i + 1], b = d[i + 2];
      if (d[i + 3] < 250) continue; // 跳过半透明边缘
      for (const k of Object.keys(targets)) {
        const [rr, gg, bb, tol] = targets[k];
        if (near(r, g, b, [rr, gg, bb], tol)) { out[k]++; break; }
      }
    }
    return out;
  }, b64);
}

