    rectHolePath(CH.x, -CH.z, CH.w, CH.d) // (d) 快门开口槽（磁头通道，真镂空）
  ]);
  const geom = new THREE.ExtrudeGeometry(shape, { depth: 2, bevelEnabled: false });
  geom.translate(0, 0, -1);              // 居中：局部 Y ∈ [-1, 1]
  buildMesh(g, geom, fillMat(FILL, FADE_OPACITY));

  // (b) 标签凹槽：主体上表面略下方 0.2 的薄盒（约 36 x 22），描边穿透显示
  const labelRecess = new THREE.BoxGeometry(36, 0.2, 22);
  labelRecess.translate(0, 0.8, 2);
  buildMesh(g, labelRecess, fillMat(FILL, FADE_OPACITY), { depthTest: false });

  // (c) 内部凹槽：标签凹槽下方较小的滑盖滑动凹陷区（约 20 x 10）
  const slideRecess = new THREE.BoxGeometry(20, 0.2, 10);
  slideRecess.translate(0, 0.85, -12);
  buildMesh(g, slideRecess, fillMat(FILL, FADE_OPACITY), { depthTest: false });

  // (e) 方向箭头：Shutter 开口附近的小三角形（几条 Line）
  const arrowPts = [
    [[-9, 1.02, 8], [-3, 1.02, 8]],
    [[-9, 1.02, 8], [-6, 1.02, 14]],
    [[-3, 1.02, 8], [-6, 1.02, 14]]
  ];
  arrowPts.forEach(([a, b]) => {
    const lg = new THREE.BufferGeometry().setFromPoints([
      new THREE.Vector3(...a), new THREE.Vector3(...b)
    ]);
    g.add(new THREE.Line(lg, edgeMat()));
  });

  return g;
}

/* ============================================================================
   3.2 / 3.5 DUST LINER —— C 字形带切口圆环（上层 / 下层同构）
   ========================================================================== */
function createDustLiner() {
  const g = new THREE.Group();
  const R = 26, r = 13;

  // 磁头通道方位（世界 → shape 平面角度；shape 的 +Y 旋转后映射到世界 -Z）
  const a = -Math.atan2(CH.z, CH.x);
  const half = Math.asin((8 / 2) / R);   // 缺口半角（外缘弦宽约 8）
  const a1 = a - half, a2 = a + half;

  const s = new THREE.Shape();
  s.moveTo(R * Math.cos(a1), R * Math.sin(a1)); // 缺口左缘（外圈）
  s.lineTo(r * Math.cos(a1), r * Math.sin(a1)); // 径向向内
  s.lineTo(r * Math.cos(a2), r * Math.sin(a2)); // 内圈弦（缺口底）
  s.lineTo(R * Math.cos(a2), R * Math.sin(a2)); // 径向向外
  s.absarc(0, 0, R, a2, a1 + Math.PI * 2, false); // 剩余约 339° 的长弧
  s.closePath();
  s.holes.push(circleHolePath(0, 0, r));         // 内圆孔

  const geom = new THREE.ExtrudeGeometry(s, { depth: 0.05, bevelEnabled: false });
  geom.translate(0, 0, -0.025);
  buildMesh(g, geom, fillMat(FILL, FADE_OPACITY));
  return g;
}

/* ============================================================================
   3.3 MAGNETIC DISK —— 唯一有实体填充的部件
   ========================================================================== */
function createMagneticDisk() {
  const g = new THREE.Group();
  const geom = new THREE.CylinderGeometry(22, 22, 0.3, 64);
  buildMesh(g, geom, fillMat(DISK_COLOR, DISK_OPACITY));

  // 表面数据轨道反光：两三条短斜线
  const segs = [
    [[-8, 0.16, -3], [-2, 0.16, 3]],
    [[3, 0.16, 2], [7, 0.16, -2]],
    [[-5, 0.16, 7], [1, 0.16, 3]]
  ];
  segs.forEach(([a, b]) => {
    const lg = new THREE.BufferGeometry().setFromPoints([
      new THREE.Vector3(...a), new THREE.Vector3(...b)
    ]);
    g.add(new THREE.Line(lg, edgeMat()));
  });
  return g;
}

/* ============================================================================
   3.4 HUB —— 中心金属盘（主轴圆孔 + 驱动方孔）
   ========================================================================== */
function createHub() {
  const g = new THREE.Group();
  const s = new THREE.Shape();
  s.absarc(0, 0, 5, 0, Math.PI * 2, false);
  addHoles(s, [
    circleHolePath(0, 0, 1.5),     // 中央主轴圆孔
    rectHolePath(2.2, 0, 1.4, 1.4) // 旁边驱动卡口方孔
  ]);
  const geom = new THREE.ExtrudeGeometry(s, { depth: 0.4, bevelEnabled: false });
  geom.translate(0, 0, -0.2);
  buildMesh(g, geom, fillMat(FILL, FADE_OPACITY));
  return g;
}

/* ============================================================================
   3.6 BOTTOM SHELL —— 复合结构
   ========================================================================== */
function createBottomShell() {
  const g = new THREE.Group();

  const shape = chamferRectShape(60, 60, 3);
  addHoles(shape, [
    circleHolePath(0, 0, 7),                // (b) 中央主轴孔 φ14 真镂空
    rectHolePath(CH.x, -CH.z, CH.w, CH.d),  // (g) 快门开口槽（与上壳/快门对位）
    rectHolePath(28, 28, 3, 3)              // (f) WRITE PROTECT NOTCH（右后角）
  ]);
  const geom = new THREE.ExtrudeGeometry(shape, { depth: 2, bevelEnabled: false });
  geom.translate(0, 0, -1);
  buildMesh(g, geom, fillMat(FILL, FADE_OPACITY));

  // (a) 中央大圆凹陷（磁片容纳区）：叠在上表面略下方的薄圆柱 φ44
  const disc = new THREE.CylinderGeometry(22, 22, 0.3, 64);
  disc.translate(0, 0.8, 0);
  buildMesh(g, disc, fillMat(FILL, FADE_OPACITY), { interior: true });

  // (c) 四角定位柱（螺丝柱 / 定位销）
  [[24, 24], [-24, 24], [24, -24], [-24, -24]].forEach(([x, z]) => {
    const col = new THREE.CylinderGeometry(1.5, 1.5, 0.9, 24);
    col.translate(x, 0.45, z);
    buildMesh(g, col, fillMat(FILL, FADE_OPACITY), { interior: true });
  });

  // (d) LIFTER：中下方小矩形凸起（约 8 x 4 x 1）
  const lifter = new THREE.BoxGeometry(8, 0.8, 4);
  lifter.translate(0, 1.0, -12);
  buildMesh(g, lifter, fillMat(FILL, FADE_OPACITY), { interior: true });

  // (e) SHUTTER SPRING 区：前边缘中部小矩形凹槽（约 10 x 4），避开磁头通道
  const spring = new THREE.BoxGeometry(10, 0.2, 4);
  spring.translate(4, 0.85, 26);
  buildMesh(g, spring, fillMat(FILL, FADE_OPACITY), { interior: true });

  return g;
}

/* ============================================================================
   3.7 SHUTTER —— 不透明金属滑盖（材质与开孔规范必须严格遵守）
   ----------------------------------------------------------------------------
   自检：
   1) 本体 MeshBasicMaterial(#4a5568, transparent=false)，不做幽灵半透明；
   2) 开孔为 Shape+holes 真镂空矩形，板面上偏左（x:-9..-3），
      开孔短边(6) ∥ 快门长边(X=24)、长边(14) ∥ 快门短边(Z=18)；
   3) 与 TOP SHELL (d) / BOTTOM SHELL (g) 复用同一 CH 参数 → 组装态三孔对齐。
   ========================================================================== */
function createShutter() {
  const g = new THREE.Group();

  const s = new THREE.Shape();
  s.moveTo(-12, -9);
  s.lineTo(-12, 9);
  s.lineTo(12, 9);
  s.lineTo(12, -9);
  s.closePath();
  s.holes.push(rectHolePath(CH.x, 0, CH.w, CH.d)); // 世界 z:-7..7（板中心 z=0）

  const geom = new THREE.ExtrudeGeometry(s, { depth: 1, bevelEnabled: false });
  geom.translate(0, 0, -0.5);

  const metal = new THREE.MeshBasicMaterial({
    color: SHUTTER_COLOR,
    transparent: false,     // 不透明金属板（必须）
    depthWrite: true
  });
  g.add(new THREE.Mesh(geom, metal));
  g.add(new THREE.LineSegments(new THREE.EdgesGeometry(geom, 15), edgeMat()));
  return g;
}

/* ============================================================================
   3.7 WRITE PROTECT TAB —— 防写入滑块（约 3 x 2 x 3）
   ========================================================================== */
function createWriteProtectTab() {
  const g = new THREE.Group();
  const geom = new THREE.BoxGeometry(3, 2, 3);
  buildMesh(g, geom, fillMat(FILL, FADE_OPACITY));
  return g;
}

/* ============================================================================
   场景装配
   ========================================================================== */
const interiorEdgeMats = [];   // 下壳内部细节描边（组装态被遮挡 / 爆炸态 X-Ray）

const topShell    = createTopShell();
const linerTop    = createDustLiner();
const disk        = createMagneticDisk();
const hub         = createHub();
const linerBottom = createDustLiner();
const bottomShell = createBottomShell();
const shutter     = createShutter();
const writeTab    = createWriteProtectTab();

[topShell, linerTop, disk, hub, linerBottom, bottomShell, shutter, writeTab]
  .forEach((o) => scene.add(o));

const faders = [];             // 所有需要手动补间 opacity 的线材

/* 下壳内部细节刻线：组装态被不透明壳体遮挡（depthTest=true），
   爆炸时切 X-Ray 并淡入，收回末尾同步淡出，避免在不透明壳上"穿模闪现"。 */
const interiorFaders = [];
interiorEdgeMats.forEach((m) => {
  m.depthTest = true;
  m.opacity = 1;
  const f = { mat: m, obj: null, from: 0, to: 0, start: 0, dur: 0, done: true };
  faders.push(f);
  interiorFaders.push(f);
});

/* ---------------- 虚线（垂直 x4 + 斜向 x2）与引线 / 标注 ---------------- */
const dashedFaders = [];

function dashedLine(from, to) {
  const geom = new THREE.BufferGeometry().setFromPoints([from, to]);
  const mat = new THREE.LineDashedMaterial({
    color: INK, dashSize: 1.4, gapSize: 0.9,
    transparent: true, opacity: 0, renderOrder: 2
  });
  const line = new THREE.Line(geom, mat);
  line.computeLineDistances(); // LineDashedMaterial 必须
  line.visible = false;
  dashedGroup.add(line);
  const f = { mat, obj: line, from: 0, to: 0, start: 0, dur: 0, done: true };
  faders.push(f);
  dashedFaders.push(f);
  return line;
}

const dashedGroup = new THREE.Group();

// 4 条垂直虚线：穿过主体的四个切角位置（切角中点 ±28.5），贯穿 Top → Bottom
[[28.5, 28.5], [-28.5, 28.5], [28.5, -28.5], [-28.5, -28.5]].forEach(([x, z]) => {
  dashedLine(new THREE.Vector3(x, -17, z), new THREE.Vector3(x, 47, z));
});

// 斜向虚线：SHUTTER / WRITE PROTECT TAB → 下壳对应槽位
dashedLine(new THREE.Vector3(-21, -14.2, 42),   new THREE.Vector3(0, -14.2, 21));
dashedLine(new THREE.Vector3(49.5, -14.2, -49.5), new THREE.Vector3(28.5, -14.2, -28.5));

scene.add(dashedGroup);

const labels = [];     // 按"从上到下"顺序排列，用于逐个淡入

function addLabel(text, anchor, fromPoint) {
  const el = document.createElement('div');
  el.className = 'label';
  el.textContent = text;

  const obj = new CSS2DObject(el);
  obj.position.set(...anchor);
  obj.visible = false;
  scene.add(obj);

  const lg = new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(...fromPoint),
    new THREE.Vector3(...anchor)
  ]);
  const lmat = new THREE.LineBasicMaterial({
    color: INK, transparent: true, opacity: 0, renderOrder: 2
  });
  const leader = new THREE.Line(lg, lmat);
  leader.visible = false;
  scene.add(leader);

  const f = { mat: lmat, obj: leader, from: 0, to: 0, start: 0, dur: 0, done: true };
  faders.push(f);
  labels.push({ el, obj, leader, fader: f });
}

addLabel('HD NOTCH',           [-34, 50, 27],  [-28, 46.6, 28]);
addLabel('TOP SHELL',          [-46, 52, 16],  [29, 46.5, 28]);
addLabel('DUST LINER',         [-36, 31, 13],  [-24.4, 30.05, 8.8]);
addLabel('MAGNETIC DISK',      [-38, 16, -12], [-21, 15.16, -6.6]);
addLabel('HUB',                [14, 20, 5],    [4.7, 18.22, 1.7]);
addLabel('DUST LINER',         [-36, -1, -13], [-24.4, 0.05, -8.8]);
addLabel('BOTTOM SHELL',       [-46, -21, 16], [-29, -13.9, 28]);
addLabel('LIFTER',             [12, -22, -16], [4, -13.9, -12]);
addLabel('SHUTTER SPRING',     [8, -26, 34],   [4, -14, 26]);
addLabel('WRITE PROTECT NOTCH',[38, -23, -37], [28, -13.9, -28]);
addLabel('SHUTTER',            [-40, -22, 58], [-30, -14.4, 47]);
addLabel('WRITE PROTECT TAB',  [56, -19, -62], [49.5, -13.8, -49.5]);

/* ============================================================================
   动画架构：parts 统一推进位置 + 材质透明度
   ========================================================================== */
let parts = [];

function setupParts() {
  const defs = [
    //  [Group, assembledPos, explodedPos, delay(ms)]  — 自上而下依次 80ms 错峰
    [topShell,    new THREE.Vector3(0, 1.5, 0),   new THREE.Vector3(0, 45, 0),    0],
    [linerTop,    new THREE.Vector3(0, 1, 0),     new THREE.Vector3(0, 30, 0),    80],
    [hub,         new THREE.Vector3(0, 0.7, 0),   new THREE.Vector3(0, 18, 0),    160],
    [disk,        new THREE.Vector3(0, 0.5, 0),   new THREE.Vector3(0, 15, 0),    240],
    [linerBottom, new THREE.Vector3(0, 0, 0),     new THREE.Vector3(0, 0, 0),     320],
    [bottomShell, new THREE.Vector3(0, -1.5, 0),  new THREE.Vector3(0, -15, 0),   400],
    [shutter,     new THREE.Vector3(0, -1.5, 21), new THREE.Vector3(-21, -15, 42), 480],
    [writeTab,    new THREE.Vector3(28.5, -1, -28.5), new THREE.Vector3(49.5, -15, -49.5), 560]
  ];

  const maxDelay = 560;
  defs.forEach(([group, from, to, delay]) => {
    group.position.copy(from);
    const mats = [];
    group.traverse((o) => {
      if (!o.isMesh) return;
      const arr = Array.isArray(o.material) ? o.material : [o.material];
      arr.forEach((m) => {
        if (m.userData && m.userData.fade) mats.push(m); // SHUTTER 金属材质无此标记
      });
    });
    parts.push({
      group, from, to, mats,
      delayExp: delay / ANIM_DURATION,
      delayCol: (maxDelay - delay) / ANIM_DURATION // 收回时错峰反向
    });
  });
}

/* ============================================================================
   相机交互（OrbitControls）
   ========================================================================== */
let controls;

function setupControls() {
  controls = new OrbitControls(camera, renderer.domElement);

  controls.enableDamping = true;
  controls.dampingFactor = 0.08;
  controls.enablePan = true;
  controls.enableRotate = true;
  controls.enableZoom = true;   // 滚轮 / 中键缩放
  controls.zoomSpeed = 0.9;

  // 显式按键行为：左旋转 / 中键或滚轮缩放 / 右平移
  controls.mouseButtons = {
    LEFT: THREE.MOUSE.ROTATE,
    MIDDLE: THREE.MOUSE.DOLLY,
    RIGHT: THREE.MOUSE.PAN
  };

  // 正交相机：用 minZoom / maxZoom 限制滚轮缩放
  controls.minZoom = 0.5;
  controls.maxZoom = 2.4;
  controls.target.set(0, 0, 0);
  controls.update();
}

/* ============================================================================
   动画状态机 / 触发
   ========================================================================== */
let animState = 'assembled';   // assembled | exploding | exploded | collapsing
let animStart = 0;
let labelTimers = [];

function easeInOutCubic(t) {
  return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
}

function fadeTo(f, to, dur) {
  f.from = f.mat.opacity;
  f.to = to;
  f.start = performance.now();
  f.dur = dur;
  f.done = false;
}

function clearTimers() {
  labelTimers.forEach((id) => clearTimeout(id));
  labelTimers = [];
}

function setInteriorXray(xray) {
  // 爆炸态：内部细节描边切 X-Ray（depthTest=false）；组装态恢复遮挡。
  interiorEdgeMats.forEach((m) => { m.depthTest = !xray; });
}

// === ANIMATION: explode trigger ===
function triggerExplode() {
  animState = 'exploding';
  animStart = performance.now();
  document.getElementById('hint').classList.add('hidden');
  setInteriorXray(true);
  // 内部刻线先归零，再略微延迟淡入，与壳体变透明的节奏同步
  interiorFaders.forEach((f) => { f.done = true; f.mat.opacity = 0; });
  labelTimers.push(setTimeout(() => {
    interiorFaders.forEach((f) => fadeTo(f, 1, 600));
  }, 250));
}

// === ANIMATION: collapse trigger ===
function triggerCollapse() {
  clearTimers();
  hideLabels();                       // 先淡出标注（约 0.3s）
  animState = 'collapsing';
  animStart = performance.now() + 320; // 再启动收回
  // 收回的最后约 0.8s，内部刻线先行淡出
  labelTimers.push(setTimeout(() => {
    interiorFaders.forEach((f) => fadeTo(f, 0, 700));
  }, 320 + 2200));
}

// === ANIMATION: labels fade-in ===
function showLabels() {
  clearTimers();

  // 爆炸完成 +200ms：4 条垂直虚线（含斜向虚线）先淡入
  labelTimers.push(setTimeout(() => {
    dashedGroup.children.forEach((l) => { l.visible = true; });
    dashedFaders.forEach((f) => fadeTo(f, 1, 600));
  }, 200));

  // 再延迟 200ms：标签按从上到下顺序、每个间隔 60ms 淡入
  labels.forEach((l, i) => {
    labelTimers.push(setTimeout(() => {
      l.obj.visible = true;
      l.leader.visible = true;
      fadeTo(l.fader, 1, 400);
      // 手动渲染一次 CSS2D：立即解除 display:none，随后强制回流再改 opacity，
      // CSS transition 才能正常触发（否则从 display:none 直接变 1 会瞬现）。
      labelRenderer.render(scene, camera);
      void l.el.offsetWidth;
      l.el.style.opacity = '1';
    }, 400 + i * 60));
  });
}

// === ANIMATION: labels fade-out ===
function hideLabels() {
  clearTimers();
  labels.forEach((l) => {
    l.el.style.opacity = '0';
    fadeTo(l.fader, 0, 300);
    labelTimers.push(setTimeout(() => { l.obj.visible = false; }, 430));
  });
  dashedFaders.forEach((f) => fadeTo(f, 0, 300));
}

// === ANIMATION: per-frame update ===
function updateAnimation(deltaTime, now) {
  void deltaTime;

  // 虚线 / 引线的透明度补间（easeInOutCubic）
  faders.forEach((f) => {
    if (f.done) return;
    const t = THREE.MathUtils.clamp((now - f.start) / f.dur, 0, 1);
    f.mat.opacity = THREE.MathUtils.lerp(f.from, f.to, easeInOutCubic(t));
    if (t >= 1) {
      f.done = true;
      if (f.to === 0 && f.obj) f.obj.visible = false;
    }
  });

  if (animState !== 'exploding' && animState !== 'collapsing') return;
  if (now < animStart) return; // collapse 前 0.3s 只做标注淡出

  const raw = (now - animStart) / ANIM_DURATION;
  const t = Math.min(raw, 1);
  const exploding = animState === 'exploding';

  parts.forEach((p) => {
    const d = exploding ? p.delayExp : p.delayCol;
    const pp = THREE.MathUtils.clamp((t - d) / (1 - d), 0, 1);
    const e = easeInOutCubic(pp);

    // 位置与透明度使用同一 progress（收回反向插值）
    const from = exploding ? p.from : p.to;
    const to = exploding ? p.to : p.from;
    p.group.position.lerpVectors(from, to, e);

    p.mats.forEach((m) => {
      const target = m.userData.explodedOpacity;
      m.opacity = exploding
        ? THREE.MathUtils.lerp(1, target, e)      // 合体端 1 → 展开端目标
        : THREE.MathUtils.lerp(target, 1, e);     // 收回反向回 1
    });
  });

  if (raw >= 1) {
    if (exploding) {
      animState = 'exploded';
      showLabels();
    } else {
      animState = 'assembled';
      setInteriorXray(false);
      interiorFaders.forEach((f) => { f.done = true; f.mat.opacity = 1; });
      document.getElementById('hint').classList.remove('hidden');
    }
  }
}

/* ============================================================================
   事件 / 主循环
   ========================================================================== */
window.addEventListener('keydown', (e) => {
  if (e.code !== 'Space') return;
  e.preventDefault();
  // === ANIMATION: space toggle（动画进行中忽略） ===
  if (animState === 'assembled') triggerExplode();
  else if (animState === 'exploded') triggerCollapse();
});

// 禁用右键菜单，避免遮挡右键平移
renderer.domElement.addEventListener('contextmenu', (e) => e.preventDefault());

window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.left = -FRUSTUM_HALF * camera.aspect;
  camera.right = FRUSTUM_HALF * camera.aspect;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  labelRenderer.setSize(window.innerWidth, window.innerHeight);
});

let last = performance.now();
function animate() {
  requestAnimationFrame(animate);
  const now = performance.now();
  const dt = Math.min(0.05, (now - last) / 1000);
  last = now;

  updateAnimation(dt, now);
  controls.update();

  // 平移范围钳制（避免把软盘拖出画面）
  const LIMIT = 55;
  controls.target.x = THREE.MathUtils.clamp(controls.target.x, -LIMIT, LIMIT);
  controls.target.y = THREE.MathUtils.clamp(controls.target.y, -20, 70);
  controls.target.z = THREE.MathUtils.clamp(controls.target.z, -LIMIT, LIMIT);

  renderer.render(scene, camera);
  labelRenderer.render(scene, camera);
}

setupParts();
setupControls();
last = performance.now();
animate();
</script>
</body>
</html>
